#define _POSIX_C_SOURCE 200809L
#define _DARWIN_C_SOURCE
#include <duckdb.h>
#include <inttypes.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <time.h>
#ifdef __APPLE__
#include <mach/mach.h>
#endif

enum { ROWS = 256, WARM = 5, CASES = 6, VARIANTS = 3 };
static const char *case_names[] = {"first_page", "selective_date_filter", "deep_offset", "filtered_deep_offset", "sorted_first_page", "filtered_sorted_page"};
static const char *variant_names[] = {"business_only", "pre_filter_row_number", "parquet_file_row_number"};
static uint64_t checks;
static void require(bool ok, const char *why) { checks++; if (!ok) { fprintf(stderr, "FAIL: %s\n", why); exit(1); } }
static void *allocate(size_t size) { void *p = malloc(size ? size : 1); require(p != NULL, "allocation"); return p; }
static char *copy(const char *s) { size_t n = strlen(s) + 1; char *p = allocate(n); memcpy(p, s, n); return p; }
static char *format(const char *fmt, ...) {
    va_list a, b; va_start(a, fmt); va_copy(b, a); int n = vsnprintf(NULL, 0, fmt, a); va_end(a); require(n >= 0, "format length");
    char *s = allocate((size_t)n + 1); vsnprintf(s, (size_t)n + 1, fmt, b); va_end(b); return s;
}
static void append(char **s, const char *suffix) { size_t a = strlen(*s), b = strlen(suffix); char *p = realloc(*s, a + b + 1); require(p != NULL, "append"); memcpy(p + a, suffix, b + 1); *s = p; }
static char *quote(const char *s, char q) {
    size_t n = 3; for (const char *p = s; *p; p++) n += *p == q ? 2 : 1;
    char *out = allocate(n), *p = out; *p++ = q; while (*s) { if (*s == q) *p++ = q; *p++ = *s++; } *p++ = q; *p = 0; return out;
}
static double millis(void) { struct timespec ts; require(clock_gettime(CLOCK_MONOTONIC, &ts) == 0, "monotonic clock"); return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6; }
static uint64_t resident(void) {
#ifdef __APPLE__
    struct mach_task_basic_info info; mach_msg_type_number_t size = MACH_TASK_BASIC_INFO_COUNT;
    require(task_info(mach_task_self(), MACH_TASK_BASIC_INFO, (task_info_t)&info, &size) == KERN_SUCCESS, "resident sample"); return info.resident_size;
#else
    return 0;
#endif
}
static uint64_t highwater(void) { struct rusage usage; require(getrusage(RUSAGE_SELF, &usage) == 0, "rusage");
#ifdef __APPLE__
    return (uint64_t)usage.ru_maxrss;
#else
    return (uint64_t)usage.ru_maxrss * 1024;
#endif
}
static duckdb_result query(duckdb_connection connection, const char *sql) {
    duckdb_result result = {0}; if (duckdb_query(connection, sql, &result) != DuckDBSuccess) { fprintf(stderr, "%s\nSQL: %s\n", duckdb_result_error(&result), sql); duckdb_destroy_result(&result); exit(1); } return result;
}
static void json(FILE *file, const char *s) {
    if (!s) { fputs("null", file); return; } fputc('"', file);
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) { if (*p == '"' || *p == '\\') fprintf(file, "\\%c", *p); else if (*p < 32) fprintf(file, "\\u%04x", *p); else fputc(*p, file); } fputc('"', file);
}
static uint64_t digest(duckdb_result *result, size_t columns, bool identity) {
    uint64_t h = UINT64_C(14695981039346656037); size_t n = columns + (identity ? 1 : 0);
    for (idx_t r = 0; r < duckdb_row_count(result); r++) for (idx_t c = 0; c < n; c++) {
        bool missing = duckdb_value_is_null(result, c, r); h = (h ^ (missing ? 0 : 1)) * UINT64_C(1099511628211);
        if (!missing) { char *s = duckdb_value_varchar(result, c, r); require(s != NULL, "exact text conversion"); size_t len = strlen(s);
            for (size_t shift = 0; shift < 8; shift++) h = (h ^ ((len >> (shift * 8)) & 255)) * UINT64_C(1099511628211);
            for (const unsigned char *p = (const unsigned char *)s; *p; p++) h = (h ^ *p) * UINT64_C(1099511628211); duckdb_free(s); }
    }
    return h;
}
static void output_rows(FILE *file, duckdb_result *result, size_t columns, bool identity) {
    fputs("\"business_rows\":[", file);
    for (idx_t r = 0; r < duckdb_row_count(result); r++) { if (r) fputc(',', file); fputc('[', file);
        for (idx_t c = 0; c < columns; c++) { if (c) fputc(',', file); char *s = duckdb_value_is_null(result, c, r) ? NULL : duckdb_value_varchar(result, c, r); json(file, s); duckdb_free(s); } fputc(']', file); }
    fputs("],\"record_ids\":[", file);
    if (identity) for (idx_t r = 0; r < duckdb_row_count(result); r++) { if (r) fputc(',', file); fprintf(file, "\"%" PRIu64 "\"", duckdb_value_uint64(result, columns, r)); }
    fputc(']', file);
}
int main(int argc, char **argv) {
    require(argc == 6, "usage: benchmark CASE(0..5 or inspect) VARIANT(0..2) PARQUET TEMP_DIRECTORY OUTPUT_JSON");
    bool inspect = !strcmp(argv[1], "inspect"); int test = inspect ? 0 : atoi(argv[1]), variant = atoi(argv[2]); require(test >= 0 && test < CASES && variant >= 0 && variant < VARIANTS, "case/variant bounds");
    FILE *out = fopen(argv[5], "w"); require(out != NULL, "private output");
    duckdb_config config = NULL; duckdb_database database = NULL; duckdb_connection connection = NULL; char *error = NULL;
    require(duckdb_create_config(&config) == DuckDBSuccess, "config");
    require(duckdb_set_config(config, "memory_limit", "512MB") == DuckDBSuccess, "memory limit");
    require(duckdb_set_config(config, "threads", "2") == DuckDBSuccess, "two threads");
    require(duckdb_set_config(config, "preserve_insertion_order", "true") == DuckDBSuccess, "reader order");
    require(duckdb_set_config(config, "temp_directory", argv[4]) == DuckDBSuccess, "private spill directory");
    double open_start = millis(); require(duckdb_open_ext(NULL, &database, config, &error) == DuckDBSuccess, error ? error : "private memory DB");
    duckdb_destroy_config(&config); require(duckdb_connect(database, &connection) == DuckDBSuccess, "connection"); double open_ms = millis() - open_start;
    char *path = quote(argv[3], '\''), *reader = format("read_parquet(%s)", path), *meta_reader = format("read_parquet(%s,file_row_number=true)", path);
    char *schema_sql = format("SELECT * FROM %s LIMIT 0", reader); duckdb_result schema = query(connection, schema_sql); size_t columns = (size_t)duckdb_column_count(&schema);
    require(columns == 20, "authored NYC source has 20 business fields");
    char *projection = copy(""), *order = copy("\"total_amount\" DESC NULLS LAST, \"tpep_pickup_datetime\" ASC NULLS LAST");
    for (size_t c = 0; c < columns; c++) { char *name = quote(duckdb_column_name(&schema, c), '"'); if (c) append(&projection, ","); append(&projection, name);
        if (strcmp(duckdb_column_name(&schema, c), "total_amount") && strcmp(duckdb_column_name(&schema, c), "tpep_pickup_datetime")) { append(&order, ","); append(&order, name); append(&order, " ASC NULLS LAST"); } free(name); }
    fputs("{\"engine\":", out); json(out, duckdb_library_version()); fprintf(out, ",\"open_ms\":%.6f,\"settings\":{", open_ms);
    duckdb_result settings = query(connection, "SELECT current_setting('memory_limit'),current_setting('threads'),current_setting('preserve_insertion_order'),current_setting('enable_external_file_cache')");
    const char *setting_names[] = {"memory_limit", "threads", "preserve_insertion_order", "enable_external_file_cache"};
    for (idx_t c = 0; c < 4; c++) { if (c) fputc(',', out); json(out, setting_names[c]); fputc(':', out); char *value = duckdb_value_varchar(&settings, c, 0); json(out, value); duckdb_free(value); } duckdb_destroy_result(&settings); fputs("},\"business_schema\":[", out);
    for (size_t c = 0; c < columns; c++) { if (c) fputc(',', out); fputs("{\"name\":", out); json(out, duckdb_column_name(&schema, c)); fprintf(out, ",\"type_id\":%u}", (unsigned)duckdb_column_type(&schema, c)); } fputc(']', out);
    if (inspect) {
        char *sql = format("WITH raw AS (SELECT row_number() OVER ()::UBIGINT AS ordinal,file_row_number+1 AS expected,file_row_number AS raw_file_ordinal FROM %s) SELECT count(*),count(DISTINCT ordinal),min(ordinal),max(ordinal),count_if(ordinal<>expected),min(raw_file_ordinal),max(raw_file_ordinal) FROM raw", meta_reader);
        double started = millis(); duckdb_result result = query(connection, sql); double elapsed = millis() - started;
        const uint64_t expected[] = {3475226,3475226,1,3475226,0,0,3475225};
        for (idx_t c = 0; c < 7; c++) require(duckdb_value_uint64(&result, c, 0) == expected[c], "full-source ordinal uniqueness and metadata agreement");
        fputs(",\"inspection_sql\":", out); json(out, sql); fprintf(out, ",\"rows\":3475226,\"unique_ordinals\":3475226,\"mismatched_normalized_ids\":0,\"raw_file_ordinal_min\":0,\"raw_file_ordinal_max\":3475225,\"elapsed_ms\":%.6f", elapsed);
        duckdb_destroy_result(&result); free(sql);
    } else {
        bool identity = variant != 0, filtered = test == 1 || test == 3 || test == 5, sorted = test >= 4;
        uint64_t offset = test == 2 ? UINT64_C(1000000) : test == 3 ? UINT64_C(50000) : 0;
        char *inner = variant == 0 ? format("SELECT %s FROM %s", projection, reader) : variant == 1 ? format("SELECT %s,row_number() OVER ()::UBIGINT AS \"__dx_bench_id\" FROM %s", projection, reader) : format("SELECT %s,(file_row_number+1)::UBIGINT AS \"__dx_bench_id\" FROM %s", projection, meta_reader);
        char *sql = format("SELECT %s%s FROM (%s) raw%s%s%s%s LIMIT 256 OFFSET %" PRIu64, projection, identity ? ",\"__dx_bench_id\"" : "", inner,
            filtered ? " WHERE \"tpep_pickup_datetime\">=TIMESTAMP '2025-01-15 00:00:00' AND \"tpep_pickup_datetime\"<TIMESTAMP '2025-01-16 00:00:00'" : "",
            sorted ? " ORDER BY " : "", sorted ? order : "", sorted && identity ? ",\"__dx_bench_id\" ASC" : "", offset);
        fputs(",\"case\":", out); json(out, case_names[test]); fputs(",\"variant\":", out); json(out, variant_names[variant]); fputs(",\"sql\":", out); json(out, sql);
        fprintf(out, ",\"offset\":\"%" PRIu64 "\",\"visible_columns\":%zu,\"transport_columns\":%zu,\"runs\":[", offset, columns, columns + identity);
        uint64_t business = 0, transport = 0; duckdb_result first = {0};
        for (int run = 0; run <= WARM; run++) {
            uint64_t rss_before = resident(); double start = millis(); duckdb_result result = query(connection, sql); double query_ms = millis() - start;
            uint64_t rss_after = resident(); require(duckdb_column_count(&result) == columns + identity && duckdb_row_count(&result) == ROWS, "bounded result and hidden column separation");
            for (size_t c = 0; c < columns; c++) require(!strcmp(duckdb_column_name(&schema, c), duckdb_column_name(&result, c)) && duckdb_column_type(&schema, c) == duckdb_column_type(&result, c), "unchanged business schema");
            if (identity) { uint64_t ids[ROWS]; require(duckdb_column_type(&result, columns) == DUCKDB_TYPE_UBIGINT, "unsigned hidden identity");
                for (idx_t r = 0; r < ROWS; r++) { require(!duckdb_value_is_null(&result, columns, r), "non-null hidden identity"); uint64_t id = ids[r] = duckdb_value_uint64(&result, columns, r); require(id >= 1 && id <= 3475226, "original ordinal range");
                    for (idx_t p = 0; p < r; p++) require(id != ids[p], "unique IDs within returned page");
                    if (!filtered && !sorted) require(id == offset + r + 1, "unfiltered original row position"); }
                if (filtered) require(duckdb_value_uint64(&result, columns, 0) > ROWS, "filter did not renumber original rows");
            }
            double convert_start = millis(); uint64_t b = digest(&result, columns, false), t = digest(&result, columns, identity); double convert_ms = millis() - convert_start;
            if (!run) { business = b; transport = t; first = result; }
            else { require(business == b && transport == t, "warm exact values/identities remain stable"); duckdb_destroy_result(&result); }
            if (run) fputc(',', out); fprintf(out, "{\"kind\":\"%s\",\"query_ms\":%.6f,\"two_digest_conversions_ms\":%.6f,\"resident_before_bytes\":\"%" PRIu64 "\",\"resident_after_bytes\":\"%" PRIu64 "\"}", run ? "warm" : "fresh_database_first_data_query", query_ms, convert_ms, rss_before, rss_after);
        }
        fprintf(out, "],\"business_fnv64\":\"%016" PRIx64 "\",\"transport_fnv64\":\"%016" PRIx64 "\",", business, transport); output_rows(out, &first, columns, identity); duckdb_destroy_result(&first);
        char *explain_sql = format("EXPLAIN %s", sql); duckdb_result plan = query(connection, explain_sql); char *plan_text = duckdb_value_varchar(&plan, 1, 0);
        fputs(",\"explain\":", out); json(out, plan_text); duckdb_free(plan_text); duckdb_destroy_result(&plan); free(explain_sql); free(inner); free(sql);
    }
    fprintf(out, ",\"peak_resident_bytes\":\"%" PRIu64 "\",\"checks\":\"%" PRIu64 "\"}\n", highwater(), checks); fclose(out);
    duckdb_destroy_result(&schema); free(path); free(reader); free(meta_reader); free(schema_sql); free(projection); free(order); duckdb_disconnect(&connection); duckdb_close(&database); duckdb_free(error); return 0;
}
